-- Insert Quiz Questions for Lesson: Adapt, Preview, and Schedule

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 16 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 16 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'adapt-preview-schedule' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson adapt-preview-schedule not found in module 16';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What must finish before switching channels or changing channel options?', 
    '["Media uploading","Comment approval","Payment processing","Account verification"]'::jsonb,
    'Media uploading',
    'Media uploading must finish before switching channels or changing channel options to ensure all platforms receive the correct media.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which setting should be checked before choosing the scheduled hour?', 
    '["The LeadProspectrr location timezone","The user''s password","The browser language","The screen resolution"]'::jsonb,
    'The LeadProspectrr location timezone',
    'The LeadProspectrr location timezone must be checked before scheduling to ensure posts publish at the intended local time.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Should every platform version always use identical wording?', 
    '["Yes, identical wording is required","No, wording and media should fit each platform","Only if the post is an advertisement","Yes, but hashtags can differ"]'::jsonb,
    'No, wording and media should fit each platform',
    'The idea may remain the same, but wording and media should fit each platform''s audience, format, and best practices.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


