-- Insert Quiz Questions for Lesson: Manage Posts and Fix Problems

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 16 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 16 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'manage-posts-fix-problems' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson manage-posts-fix-problems not found in module 16';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should happen after a post shows Published?', 
    '["Delete the post immediately","Open and check the live post","Schedule another post right away","Change the post status to Draft"]'::jsonb,
    'Open and check the live post',
    'After a post shows Published, open and check the live post on the platform to ensure it looks correct and the link works.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Name two common causes of a failed post.', 
    '["Expired connection and missing permission","Too many likes and comments","High engagement rate","Correct timezone settings"]'::jsonb,
    'Expired connection and missing permission',
    'Common causes of failed posts include expired connections, missing permissions, unsupported media, invalid wording, or broken links.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which two views help you manage planned posts?', 
    '["Calendar and list views","Map and chart views","Grid and timeline views","Report and analytics views"]'::jsonb,
    'Calendar and list views',
    'Calendar and list views in Social Planner help you manage planned posts, check statuses, and identify issues.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


